  PATTERNS: [
    ["Could you ~?","Magalang na hiling: \"Puwede mo bang…?\" Mas malumanay kaysa sa \"Can you\"","Could you help me with this?","polite"],
    ["Would you mind ~ing?","Napakagalang na hiling: \"Ayos lang ba kung…?\" Kapag payag ka, \"No\" ang sagot (hindi ka tututol)","Would you mind closing the window?","polite"],
    ["Can I get ~?","Pag-order sa tindahan o restawran: \"Pahingi ng…\" Pinakakaraniwan sa usapan sa Amerika","Can I get a large latte?","polite"],
    ["I'd like ~","Magalang na anyo ng \"want\": \"Gusto ko sana ng…\"","I'd like a window seat, please.","polite"],
    ["a / an + noun","Isang nabibilang na bagay na unang beses binanggit. \"an\" bago ang tunog na vowel","I have an idea.","articles"],
    ["the + noun","Ang tiyak na bagay na alam ninyong dalawa kung alin","Can you open the door?","articles"],
    ["I am / You are / She is","Ang verb na \"be\": kung ano, nasaan o ano ang kalagayan ng subject. Walang katumbas sa Tagalog, kaya huwag itong laktawan","She is a nurse.","be"],
    ["Do you ~? / Does he ~?","Tanong kapag may ibang verb bukod sa \"be\". \"does\" kapag he, she o it ang subject","Does he live here?","be"],
    ["don't / doesn't + base form","Negatibo kapag may ibang verb bukod sa \"be\"","I don't eat meat.","be"],
    ["he / she / it + verb na may -s","Sa present tense, dagdagan ng -s ang verb kapag he, she o it ang subject","My sister works at a hospital.","be"],
    ["be + -ing","Ginagawa ngayon mismo, o nakaplano na sa malapit na hinaharap","I'm meeting Jake tonight.","tense"],
    ["verb + -ed / irregular na past form","Tapos nang pangyayari (went, ate, saw…). Kailangan ang past form kahit may salitang pampanahon na","I went to Cebu last week.","tense"],
    ["will + base form","Pasyang ginawa habang nagsasalita, pangako o hula","I'll call you later.","tense"],
    ["be going to + base form","Bagay na naplano na bago pa magsalita","I'm going to visit my parents this weekend.","tense"],
    ["Have you ever ~?","Tanong tungkol sa karanasan: \"Nasubukan mo na bang…?\"","Have you ever tried adobo?","tense"],
    ["in + buwan / taon / panahon","Mahabang saklaw ng panahon","My birthday is in June.","prep"],
    ["on + araw / petsa","Isang tiyak na araw","The party is on Saturday.","prep"],
    ["at + oras / tiyak na lugar","Eksaktong oras o isang tiyak na punto","Let's meet at 7 at the station.","prep"],
    ["How about ~ing?","Mungkahi: \"Paano kung… tayo?\"","How about getting lunch together?","smalltalk"],
    ["So do I / Neither do I","Pagsang-ayon: \"Ako rin\" (positibo / negatibo). Kaswal: \"Me too\" / \"Me neither\"","I love this song. / So do I.","smalltalk"],
    ["verb + it + adverb","Kapag pronoun ang object ng phrasal verb, nasa gitna ito","Can you turn it down?","phrasal"],
    ["look forward to + -ing","Preposition ang \"to\" rito, kaya anyong -ing ang kasunod","I'm looking forward to hearing from you.","phrasal"],
    ["It's + oras","Pagsasabi ng oras: basahin ang oras, tapos ang minuto","It's ten fifteen.","numbers"],
    ["I'm writing to ~","Pagsasabi ng layunin sa unang pangungusap ng email","I'm writing to confirm our meeting.","email"],
    ["Let me know if ~","\"Sabihan mo ako kung…\" Karaniwang pangwakas ng email","Let me know if you need anything else.","email"]
  ],
